<template>
  <view class="mes-page">
    <view class="mes-header"><view><view class="mes-title">交接班</view><view class="mes-description">交班人保存草稿，提交后由指定接班人本人确认。工单状态和产量保留交班时的快照。</view></view><button size="mini" :disabled="loading || saving" @click="reload">刷新交接班</button></view>
    <view v-if="error" class="mes-error">{{ error }}</view>
    <view v-if="authorized"><view class="mes-toolbar"><input v-model="filters.dateFrom" class="mes-search" placeholder="开始日期 YYYY-MM-DD" /><input v-model="filters.dateTo" class="mes-search" placeholder="结束日期 YYYY-MM-DD" /><view class="mes-filter"><uni-data-select v-model="filters.status" :localdata="states" :clear="false" /></view><button size="mini" :disabled="loading" @click="search">查询</button><button size="mini" :disabled="saving" @click="newDraft">新建交班草稿</button></view>
      <view class="ops-layout ops-layout-list ops-section">
        <view class="ops-panel"><view class="ops-panel-title">交接班清单 · {{ total }} 条</view><view class="mes-table"><uni-table border :loading="loading" :emptyText="error ? '读取失败，请重新加载' : '暂无交接班记录'"><uni-tr><uni-th>日期 / 工序</uni-th><uni-th>班次 / 车间</uni-th><uni-th>交班 → 接班人员</uni-th><uni-th>关联批号</uni-th><uni-th width="110">状态</uni-th><uni-th width="100">操作</uni-th></uni-tr><uni-tr v-for="row in rows" :key="row._id"><uni-td><view class="ops-cell-stack"><text>{{ row.date }}</text><text class="ops-row-title">{{ row.processName }}</text></view></uni-td><uni-td><view class="ops-cell-stack"><text>{{ row.shiftName }} → {{ row.nextShiftName }}</text><text class="ops-table-note">{{ row.workshopName }}</text></view></uni-td><uni-td>{{ row.authorName }} → {{ row.receiverName }}</uni-td><uni-td><text class="ops-batch">{{ (row.batchNos || []).join('、') || '未关联工单' }}</text></uni-td><uni-td><text class="ops-status" :class="row.status === 'received' ? 'success' : row.status === 'submitted' ? 'warning' : 'muted'">{{ stateName(row.status) }}</text></uni-td><uni-td><button size="mini" :disabled="saving" @click="viewRecord(row)">查看</button></uni-td></uni-tr></uni-table></view><view class="mes-pagination"><uni-pagination show-icon :total="total" :page-size="20" :current="page" @change="changePage" /></view></view>
        <operation-drawer :open="showEditor" :title="editing ? (form._id ? '编辑交班草稿' : '新建交班草稿') : '交接班详情'" :busy="saving || jobsLoading" @close="showEditor = false"><view class="ops-panel ops-editor-panel">
          <template v-if="editing"><view class="ops-panel-title">{{ form._id ? '编辑本人草稿' : '新建本人交班草稿' }}</view><view class="ops-hint">接班人员须属于同一车间和工序并绑定实际账号。提交后内容锁定，等待本人接班确认。</view><operation-fields v-model="form" :fields="fields" :disabled="saving" /><view class="ops-section"><view class="mes-toolbar"><input v-model="jobKeyword" class="mes-search" placeholder="用完整批号查找关联工单" @confirm="searchJobs" /><button size="mini" :disabled="jobsLoading || saving" @click="searchJobs">查找工单</button></view><view class="ops-hint">选择下方同一车间和工序的工单，可继续搜索后添加更多批号。</view><operation-fields v-model="form" :fields="jobFields" :disabled="saving || jobsLoading" /><view v-if="jobError" class="mes-error">{{ jobError }}</view></view><view class="mes-footer"><button type="primary" size="mini" :disabled="saving" @click="save">{{ saving ? '保存中…' : '保存交班草稿' }}</button></view></template>
          <template v-else-if="selected"><view class="ops-panel-title">{{ selected.date }} · {{ selected.processName }}<text class="ops-state">{{ stateName(selected.status) }}</text></view><view class="ops-row-detail">{{ selected.workshopName }}<view>{{ selected.authorName }} · {{ selected.shiftName }} → {{ selected.receiverName }} · {{ selected.nextShiftName }}</view><view>提交：{{ formatDate(selected.submittedAt) }} · 接班：{{ formatDate(selected.receivedAt) }}</view></view><view class="ops-section"><view class="ops-row-title">交班内容</view><view class="ops-note">{{ selected.content }}</view></view><view v-for="field in detailFields" :key="field.key" class="ops-section"><view class="ops-row-title">{{ field.label }}</view><view class="ops-note">{{ selected[field.key] || '未填写' }}</view></view><view v-if="(selected.jobSnapshots || []).length" class="ops-section"><view class="ops-row-title">交班时的工单内容</view><view v-for="job in selected.jobSnapshots" :key="job._id" class="ops-row"><view><view class="ops-batch">{{ job.batchNo }} · {{ stateName(job.state) }}</view><view class="ops-row-detail">工单 v{{ job.version }} · 订单 v{{ job.orderVersion }}<view>合格 {{ job.goodQty || 0 }} / 不良 {{ job.defectQty || 0 }} / 目标 {{ job.targetQty }} {{ unitName(job.unit) }}</view></view></view><button size="mini" @click="openJob(job._id)">当前工单</button></view></view><view v-if="selected.status !== 'received'" class="ops-section"><view class="mes-field"><text class="mes-field-label">提交 / 接班说明（可选）</text><textarea v-model="commandNote" :disabled="saving" maxlength="2000" placeholder="补充交接情况或接班核对结果" /></view><view class="mes-footer"><button v-if="selected.status === 'draft' && selected.authorId === uid" size="mini" :disabled="saving" @click="editSelected">编辑本人草稿</button><button v-if="selected.status === 'draft'" type="primary" size="mini" :disabled="saving" @click="command('submit')">提交交班</button><button v-if="selected.status === 'submitted' && canReceive" type="primary" size="mini" :disabled="saving" @click="command('receive')">本人确认接班</button><text v-if="selected.status === 'submitted' && !canReceive" class="ops-hint">等待 {{ selected.receiverName }} 使用绑定账号确认接班。</text></view></view><view v-if="selected.receiveNote" class="ops-section"><view class="ops-row-title">接班确认说明</view><view class="ops-note">{{ selected.receiveNote }}</view></view></template>
          <view v-if="formError" class="mes-error">{{ formError }}</view><view v-if="notice" class="ops-success">{{ notice }}</view>
        </view></operation-drawer>
      </view>
    </view>
  </view>
</template>
<script>
import OperationDrawer from '@/components/mes/operations/OperationDrawer.vue';
import OperationFields from '@/components/mes/operations/OperationFields.vue';
import { requireMesAdmin, formatMesDate, confirmMes } from '@/utils/mes-api.js';
import { callOperations, emptyCatalogs, options, handoverStates, stateName, unitName, today, operationRequest } from '@/utils/operations-admin.js';
function blank() { return { date: today(), nextDate: today(), shiftId: '', nextShiftId: '', processId: '', receiverId: '', jobIds: [], content: '', tailPallet: '', hygiene: '', exceptions: '', changeReason: '' }; }
export default {
  components: { OperationFields, OperationDrawer },
  data() { return { showEditor: false, uid: '', profile: {}, authorized: false, catalogs: emptyCatalogs(), rows: [], total: 0, page: 1, filters: { dateFrom: today(), dateTo: today(), status: '' }, states: handoverStates, loading: false, saving: false, error: '', formError: '', notice: '', form: blank(), editing: true, selected: null, jobs: [], jobKeyword: '', jobsLoading: false, jobError: '', saveRequest: null, commandRequest: null, commandNote: '', detailFields: [{ key: 'tailPallet', label: '末托 / 在制品' }, { key: 'hygiene', label: '卫生与现场状态' }, { key: 'exceptions', label: '待跟进问题' }] }; },
  computed: {
    fields() {
      const process = this.catalogs.processes.find(row => row._id === this.form.processId);
      const receivers = this.catalogs.personnel.filter(row => row.uid && row.uid !== this.uid && (!process || (row.workshopId === process.workshopId && (row.processIds || []).includes(process._id))));
      const fields = [{ key: 'date', label: '交班日期', type: 'date', required: true }, { key: 'shiftId', label: '交班班次', type: 'select', required: true, options: options(this.catalogs.shifts, this.form.shiftId) }, { key: 'nextDate', label: '接班日期', type: 'date', required: true }, { key: 'nextShiftId', label: '接班班次', type: 'select', required: true, options: options(this.catalogs.shifts, this.form.nextShiftId) }, { key: 'processId', label: '工序', type: 'select', required: true, options: options(this.catalogs.processes, this.form.processId) }, { key: 'receiverId', label: '指定接班人', type: 'select', required: true, options: options(receivers, this.form.receiverId) }, { key: 'content', label: '交班内容', type: 'textarea', required: true, wide: true }, { key: 'tailPallet', label: '末托 / 在制品', type: 'textarea', wide: true }, { key: 'hygiene', label: '卫生与现场状态', type: 'textarea', wide: true }, { key: 'exceptions', label: '待跟进问题', type: 'textarea', wide: true }];
      if (this.form._id) fields.push({ key: 'changeReason', label: '草稿修改原因', type: 'textarea', required: true, wide: true });
      return fields;
    },
    jobFields() { const jobs = this.jobs.filter(row => row.processId === this.form.processId); return [{ key: 'jobIds', label: '关联工单（可选）', type: 'multi', wide: true, options: jobs.map(row => ({ value: row._id, text: `${row.batchNo} · ${row.productName} · ${stateName(row.state)}` })) }]; },
    canReceive() { return this.selected && this.selected.receiverUid === this.uid && this.selected.receiverId === this.profile.personId && this.selected.authorId !== this.uid; }
  },
  async onLoad() { await this.reload(); },
  methods: {
    stateName, unitName, formatDate: formatMesDate,
    search() { this.page = 1; this.reload(); },
    changePage(event) { this.page = event.current; this.reload(); },
    openJob(id) { uni.navigateTo({ url: '/pages/mes/operations/job-detail?id=' + encodeURIComponent(id) }); },
    newDraft() { this.showEditor = true; this.form = blank(); this.editing = true; this.selected = null; this.jobs = []; this.jobKeyword = ''; this.formError = ''; this.notice = ''; this.saveRequest = null; this.commandRequest = null; },
    viewRecord(row) { this.showEditor = true; this.selected = JSON.parse(JSON.stringify(row)); this.editing = false; this.formError = ''; this.notice = ''; this.commandNote = ''; this.commandRequest = null; },
    editSelected() { if (!this.selected || this.selected.authorId !== this.uid || this.selected.status !== 'draft') return; this.form = { ...blank(), ...JSON.parse(JSON.stringify(this.selected)), changeReason: '' }; this.jobs = (this.selected.jobSnapshots || []).map(row => ({ ...row, processId: this.selected.processId })); this.editing = true; this.saveRequest = null; this.formError = ''; this.notice = ''; },
    async reload() { if (this.loading) return; this.loading = true; this.error = ''; try { if (!this.authorized) { const user = await requireMesAdmin(); this.uid = user.uid || user._id; const base = await callOperations('bootstrap'); this.catalogs = { ...emptyCatalogs(), ...base.catalogs }; this.profile = base.profile || {}; this.authorized = true; } const data = await callOperations('listHandovers', { ...this.filters, page: this.page, pageSize: 20 }); this.rows = data.list || []; this.total = data.total || 0; if (this.selected) { const latest = this.rows.find(row => row._id === this.selected._id); if (latest) this.selected = latest; } } catch (error) { this.rows = []; this.total = 0; this.error = error.message; } finally { this.loading = false; } },
    async searchJobs() { if (this.jobsLoading || this.saving) return; this.jobError = ''; if (!this.form.processId) { this.jobError = '请先选择交班工序。'; return; } if (!this.jobKeyword.trim()) { this.jobError = '请填写完整批号查找关联工单。'; return; } this.jobsLoading = true; try { const data = await callOperations('listJobs', { page: 1, pageSize: 50, keyword: this.jobKeyword.trim().toUpperCase() }); const combined = new Map(this.jobs.filter(row => this.form.jobIds.includes(row._id)).map(row => [row._id, row])); (data.list || []).forEach(row => combined.set(row._id, row)); this.jobs = [...combined.values()]; if (data.total > (data.list || []).length) this.jobError = '匹配工单较多，请输入更完整的批号缩小范围。'; else if (!this.jobs.some(row => row.processId === this.form.processId)) this.jobError = '没有匹配所选工序的工单。'; } catch (error) { this.jobError = error.message; } finally { this.jobsLoading = false; } },
    async save() {
      if (this.saving) return; this.formError = ''; this.notice = '';
      const missing = this.fields.find(field => field.required && !String(this.form[field.key] == null ? '' : this.form[field.key]).trim()); if (missing) { this.formError = '请填写或选择' + missing.label; return; }
      const { teamId, teamName, ...record } = this.form; const payload = { record, expectedVersion: Number(this.form.version) || 0 }; this.saveRequest = operationRequest(this.saveRequest, payload); this.saving = true;
      try { const result = await callOperations('saveHandover', { ...payload, requestId: this.saveRequest.id }); this.form = { ...blank(), ...result, changeReason: '' }; this.viewRecord(result); this.notice = '交班草稿已保存，核对后可提交。'; this.saveRequest = null; await this.reload(); }
      catch (error) { this.formError = error.message + (error.code === 409 ? ' 请刷新后重新打开本人最新草稿。' : ' 保持内容不变可重试。'); }
      finally { this.saving = false; }
    },
    async command(command) {
      if (this.saving || !this.selected) return;
      if (!await confirmMes(command === 'submit' ? '提交交班' : '本人确认接班', command === 'submit' ? '提交后交班内容锁定，等待指定接班人本人核对确认。' : '确认已经核对工单、末托和现场情况并接班？')) return;
      const content = { id: this.selected._id, command, note: this.commandNote }; const request = operationRequest(this.commandRequest, content); if (request !== this.commandRequest) request.expectedVersion = this.selected.version; this.commandRequest = request;
      this.saving = true; this.formError = ''; this.notice = '';
      try { const result = await callOperations('handoverCommand', { ...content, expectedVersion: request.expectedVersion, requestId: request.id }); this.selected = result; this.notice = command === 'submit' ? '已提交交班，等待本人接班。' : '本人接班已确认。'; this.commandRequest = null; await this.reload(); }
      catch (error) { this.formError = error.message + (error.code === 409 ? ' 请刷新并核对最新交接状态。' : ' 相同内容可重试。'); }
      finally { this.saving = false; }
    }
  }
};
</script>
<style lang="scss" scoped>@import './operations.scss';</style>
